package initialize

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"io"
	"strconv"
	"strings"
)

type legacyDistrictEntry struct {
	ID       int
	ParentID int
	Name     string
}

// These compact payloads preserve the remaining old-system enumerations and
// the complete three-level district tree in the deployed server binary.
const legacyFlatCategoryData = ""
const legacyDistrictData = ""

func decodeLegacyCatalog(data string) string {
	encoded, err := base64.StdEncoding.DecodeString(data)
	if err != nil {
		panic("invalid legacy catalogue encoding")
	}
	reader, err := gzip.NewReader(bytes.NewReader(encoded))
	if err != nil {
		panic("invalid legacy catalogue compression")
	}
	defer reader.Close()
	raw, err := io.ReadAll(reader)
	if err != nil {
		panic("cannot read legacy catalogue")
	}
	return string(raw)
}

func legacyFlatCategories() map[string][]string {
	result := make(map[string][]string)
	seen := make(map[string]map[string]struct{})
	for _, line := range strings.Split(strings.TrimSpace(decodeLegacyCatalog(legacyFlatCategoryData)), "\n") {
		parts := strings.Split(line, "\t")
		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
			continue
		}
		if seen[parts[0]] == nil {
			seen[parts[0]] = make(map[string]struct{})
		}
		if _, ok := seen[parts[0]][parts[1]]; ok {
			continue
		}
		seen[parts[0]][parts[1]] = struct{}{}
		result[parts[0]] = append(result[parts[0]], parts[1])
	}
	return result
}

func legacyDistrictCatalog() []legacyDistrictEntry {
	lines := strings.Split(strings.TrimSpace(decodeLegacyCatalog(legacyDistrictData)), "\n")
	entries := make([]legacyDistrictEntry, 0, len(lines))
	for _, line := range lines {
		parts := strings.Split(line, "\t")
		if len(parts) != 3 {
			continue
		}
		id, idErr := strconv.Atoi(parts[0])
		parentID, parentErr := strconv.Atoi(parts[1])
		if idErr != nil || parentErr != nil || parts[2] == "" {
			continue
		}
		entries = append(entries, legacyDistrictEntry{ID: id, ParentID: parentID, Name: parts[2]})
	}
	return entries
}
